import{_ as o,o as t,c as s,a0 as n}from"./chunks/framework.D4fUSYzX.js";const k=JSON.parse('{"title":"ADR 0114: The Consultation close takes the Delete key, so the queue removal is one key","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0114-the-consultation-close-takes-the-delete-key-the-queue-removal-is-one-key.md","filePath":"adr/0114-the-consultation-close-takes-the-delete-key-the-queue-removal-is-one-key.md"}'),a={name:"adr/0114-the-consultation-close-takes-the-delete-key-the-queue-removal-is-one-key.md"};function i(c,e,l,h,d,r){return t(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="adr-0114-the-consultation-close-takes-the-delete-key-so-the-queue-removal-is-one-key" tabindex="-1">ADR 0114: The Consultation close takes the Delete key, so the queue removal is one key <a class="header-anchor" href="#adr-0114-the-consultation-close-takes-the-delete-key-so-the-queue-removal-is-one-key" aria-label="Permalink to &quot;ADR 0114: The Consultation close takes the Delete key, so the queue removal is one key&quot;">​</a></h1><p>Status: accepted Date: 2026-10-06</p><p>Amends ADR 0037&#39;s key decision: the Consultation close no longer takes <code>w</code>. Its confirmation decisions hold unchanged.</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>ADR 0037 put the Consultation close on <code>w</code>, the key ADR 0031 gave the Ticket work-cycle close, so the two sections named their close on one key and the Key guide stated it once. The unification was between the two Closes.</p><p>The operator reads the key for a different job. Taking a start out of the Work queue is one gesture: the Work queue removes the item under the cursor with the Delete key, and the Consultation section&#39;s close is how a queued Consultation leaves that same queue. ADR 0034&#39;s queue holds the Consultation items beside the Handoff items, and the two sections that look at the same row reached for two keys - Delete in the queue, <code>w</code> in the section - to take it out. The operator asked for the removal to be one key, and for <code>w</code> to leave the Consultation section.</p><p>The Ticket work-cycle close (ADR 0031) is a different action: it ends a ticket&#39;s work cycle, not a queue row, so it keeps <code>w</code>. The Consultation section&#39;s <code>d</code> Delete is a third action - it removes a closed or unscheduled record from the history - and keeps its key.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p><strong>The Consultation close takes the Delete key, in both Consultation modes.</strong> The catalogue&#39;s <code>consultation-close</code> control claims <code>delete</code>, beside the Work queue&#39;s <code>queue-remove</code>, so the key that takes a row out of the queue answers the close in the section that lists the row. <code>w</code> is retired from the Consultation section: the catalogue resolves it there to nothing, and the Ticket section&#39;s <code>w</code> Close is untouched.</p><p><strong>The close&#39;s confirmation shape is ADR 0037&#39;s, unchanged.</strong> A close that stops a live Agent confirms first behind the shared panel and names what it keeps; a <code>missing</code>, <code>failed</code>, <code>queued</code>, or <code>unscheduled</code> Consultation closes without a dialog; a <code>closing</code> one opens the panel with its Retry and Force-close rows. The key move is in the catalogue only; the dispatch stays in the Consultation routes.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>The Key guide and the Action bar state Close on the Delete key in the Consultation section and on <code>w</code> in the Ticket section. The shared catalogue still states each close once, so the bar and the guide cannot disagree.</li><li>The Consultation section names its two removals on two keys: the Delete key closes the Consultation and, for a queued record, takes its item out of the Work queue; <code>d</code> deletes a closed or unscheduled record from the history. The keys follow the actions, and each action keeps its own refusal.</li><li>ADR 0037 is superseded in part: the close no longer takes <code>w</code>. Its confirmation decisions - confirm exactly when a live Agent is stopped, close direct on a record with no agent, refuse a closed one - hold.</li><li>ADR 0038&#39;s references to <code>w</code> as the key that opens the Consultation close panel are superseded where they name the key: the panel opens on the Delete key. Its Enter decisions hold.</li><li><code>w</code> now belongs to the Ticket section alone: the work-cycle close on a ticket, in both Ticket base modes. A key the catalogue resolves to nothing in the Consultation section answers no control there, the way <code>z</code> does.</li></ul>',12)])])}const m=o(a,[["render",i]]);export{k as __pageData,m as default};
